#include "hal.h"
#include "utils.h"
#include <stdio.h>
#include "sys_platform.h"
#include "apb2fabric.h"
#include "spi.h"
#include <riscv_errors.h>
#include "platform_init.h"
#include "device_info.h"

static const uint8_t spi_tx_data[] = {0x81, 0x82, 0x83};

#if REG_TEST_ENABLE
#include "reg_test.h"
#endif

#ifdef TERM_UART_INST_BASE_ADDR
#include "uart.h"

#ifndef _UART_NO_INTERRUPTS_
#include "pic.h"
#endif
#endif

#ifdef LED_GPIO_INST_BASE_ADDR
#include "gpio.h"
#define LED_GPIO_INDEX 1
struct gpio_instance led_gpio_inst;
#else
#define LED_COUNT 8
#endif

#if (defined TERM_UART_INST_BASE_ADDR)
struct uart_instance term_uart_core_uart;
#elif (defined TERM_LOCAL_UART_INST_BASE_ADDR)
struct local_uart_instance term_local_uart_core;
#endif

#if defined TERM_UART_INST_BASE_ADDR
#define TERM_UART_TX_POLL_LIMIT 100000U

static int term_uart_putc_timeout(char c)
{
	unsigned int attempts;

	for (attempts = 0; attempts < TERM_UART_TX_POLL_LIMIT; ++attempts) {
		if (uart_putc(&term_uart_core_uart, (unsigned char)c) == 0)
			return 0;
	}

	return EOF;
}
#endif

static int lscc_uart_putc(char c, FILE *file)
{
#ifdef LSCC_STDIO_UART_APB
		int ret = EOF;
#if (defined TERM_UART_INST_BASE_ADDR)
		ret = term_uart_putc_timeout(c);
		if (c == '\n' && ret == 0)
			ret = term_uart_putc_timeout('\r');
#elif (defined TERM_LOCAL_UART_INST_BASE_ADDR)
		ret = local_uart_putc(&term_local_uart_core, c);
		if (c == '\n' && ret == 0)
			ret = local_uart_putc(&term_local_uart_core, '\r');
#endif
		return ret;
#else
		return EOF;
#endif
}


static int lscc_uart_getc(FILE *file)
{
	(void) file;
	return EOF;
}


static int lscc_uart_flush(FILE *file)
{
	(void) file;
	return 0;
}


static int bsp_init(void)
{
	int ret = 0;
#if (defined TERM_UART_INST_BASE_ADDR)
#ifndef _UART_NO_INTERRUPTS_
	//setup uart IRQ
	pic_init(CPU_INST_0_PICTIMER_START_ADDR);
	term_uart_core_uart.intrLevel = TERM_UART_INST_IRQ;
	term_uart_core_uart.intrAvail = true;
	//pic_isr_register(UART0_INST_IRQ, uart_isr, (void *)&term_uart_core_uart);
#endif

	//initialize UART
	uart_init(&term_uart_core_uart, TERM_UART_INST_BASE_ADDR, TERM_UART_INST_SYS_CLK * 1000000, TERM_UART_INST_BAUD_RATE, 1, 8);
	term_uart_core_uart.blockingTx = 0;
#elif (defined TERM_LOCAL_UART_INST_BASE_ADDR)
    local_uart_init(&term_local_uart_core, TERM_LOCAL_UART_INST_BASE_ADDR, TERM_LOCAL_UART_INST_SYS_CLK * 1000000, TERM_LOCAL_UART_INST_BAUD_RATE, 1, 8);
#endif
	iob_init(lscc_uart_putc, lscc_uart_getc, lscc_uart_flush);

#if CPU_INST_0_PLIC_EN || CPU_INST_0_CLINT_EN
	trap_init();
#endif

#if REG_TEST_ENABLE
	/* Used for register access test, If not sure how to use, disable it. */
	reg_test_assert(mem_access_test());
	printf("\nmem_access_test success!\n\n");
#endif

#ifdef LED_GPIO_INST_BASE_ADDR
	//initialize LED GPIO
	led_gpio_inst.instance_name = LED_GPIO_INST_NAME;
	gpio_init(&led_gpio_inst, LED_GPIO_INST_BASE_ADDR, LED_GPIO_INST_LINES_NUM, LED_GPIO_INST_GPIO_DIRS);
#endif

#ifdef RISCV_RX_DRV_VER
	/*If driver support, set global interrupt-enable bit to 1.*/
#if CPU_INST_0_PLIC_EN || CPU_INST_0_CLINT_EN
	plic_enable_global_interrupts(1);
#endif
#endif
	return ret;
}


int main(void) {
#ifdef LED_GPIO_INST_BASE_ADDR
	static uint8_t led_state = 0;
#else
	static uint8_t idx = 1;
	static uint8_t pin_state = 0xFF;
#endif
	uint16_t fpga_version;
	uint16_t failed_rw_reg = UINT16_MAX;
	apb2fabric_status_t apb_status;
	apb2fabric_rw_check_status_t rw_check_status;
	spi_slave_t failed_slave = SPI_SLAVE_COUNT;
	spi_status_t spi_result;

	bsp_init();

	printf("Started!\nHello RISC-V world!\n");

	rw_check_status = apb2fabric_check_rw_registers(&failed_rw_reg);
	if (rw_check_status == APB2FABRIC_RW_CHECK_OK)
		printf("FPGA R/W register check passed\n");
	else
		printf("FPGA R/W register check failed at index %u (status %u)\n",
				(unsigned)failed_rw_reg, (unsigned)rw_check_status);

	apb_status = apb2fabric_reg_read(APB2FABRIC_REG_VERSION, &fpga_version);
	if (apb_status == APB2FABRIC_STATUS_OK)
		printf("FPGA register version: 0x%04X\n", fpga_version);
	else
		printf("FPGA version read failed (status %u)\n", (unsigned)apb_status);

	if (rw_check_status == APB2FABRIC_RW_CHECK_OK) {
		spi_result = spi_transfer_round_robin(spi_tx_data,
				(uint16_t)sizeof(spi_tx_data), &failed_slave);
		if (spi_result == SPI_STATUS_OK)
			printf("SPI write completed for ADC, DAC, and flash\n");
		else if (failed_slave < SPI_SLAVE_COUNT)
			printf("SPI write failed for slave %u (status %u)\n",
					(unsigned)failed_slave, (unsigned)spi_result);
		else
			printf("SPI round-robin write failed (status %u)\n",
					(unsigned)spi_result);
	}

	while (true) {
#ifdef LED_GPIO_INST_BASE_ADDR
		gpio_output_write(&led_gpio_inst, LED_GPIO_INDEX,
				led_state ? (1U << LED_GPIO_INDEX) : 0U);
		led_state ^= 1U;
#else
		printf("0x%02X\n",(pin_state ^ (1<<idx)));

		if (++idx == LED_COUNT) {
			idx = 0;
			pin_state = ~pin_state;
		}
#endif

		if (RTL_SIM) {
			delay(1);
		} else {
			delay(200);
		}
	}

	return 0;
}

